\title{Output-Distribution Distillation for Contextual Sparsity Prediction in SwiGLU LLMs}

\author{Anonymous}

\begin{document}
\maketitle

\begin{abstract}
\input{abstract}
\end{abstract}

\input{introduction}
\input{related_work}
\input{method}
\input{experiments}
\input{conclusion}
\input{limitations}
\input{ethics}

\bibliography{references}

\input{appendix}

